import { Worker } from 'node:worker_threads';
async function main(): Promise<void> {
  const worker = new Worker(`const { parentPort } = require('node:worker_threads'); parentPort.onmessage = (event) => { parentPort.postMessage('got ' + JSON.stringify(event.data)); parentPort.close(); };`, { eval: true });
  worker.on('message', (v: any) => { console.log(v); });
  worker.postMessage({ k: 1 });
  await new Promise<void>((resolve) => { worker.on('exit', () => { resolve(); }); });
}
